// AI: below section was generated by an AI
// fxsim headless checker. Usage: node check.js [--golden] [fx files...]   (default files: fx_p*.js in this folder)
// Runs every effect registered by the given files: 3 slider sets x len 30/150 x 500 frames; prints PASS/FAIL, ms/frame and gzip sizes.
"use strict";
const fs = require("fs"), path = require("path"), zlib = require("zlib");
const DIR = __dirname, REPO = "C:\\Users\\DigvijayPatilLM\\Downloads\\WLED-main\\WLED-main";
const FXS = require(path.join(DIR, "core.js")), H = FXS.H;
const args = process.argv.slice(2), golden = args.includes("--golden");
let files = args.filter(a => !a.startsWith("--"));
if (!files.length) files = fs.readdirSync(DIR).filter(f => /^fx_p\d+\.js$/.test(f)).sort();
files = files.map(f => path.resolve(DIR, f));

// effects that are static on the device too (never fail for "no animation"); ports can also pass {static:true}
const STATIC = new Set(["Solid", "Solid Pattern", "Solid Pattern Tri", "Image", "Copy Segment", "Percent"]);
const FRAMES = 500, LENS = [30, 150], MAXMS = 2, gz = s => zlib.gzipSync(s).length;

// palettes: palettes_demo.json (palx format) or a small inline set: FastLED 16-entry, gradient, "c1" markers
const demo = path.join(DIR, "palettes_demo.json");
let P;
if (fs.existsSync(demo)) { const j = JSON.parse(fs.readFileSync(demo, "utf8")); P = j.p || j; if (Array.isArray(j)) P = Object.assign({}, ...j.map(x => x.p || x)); }
else P = {
	6: [[0,155,0,213],[16,189,0,184],[32,218,0,146],[48,243,0,92],[64,244,85,0],[80,220,143,0],[96,213,180,0],[112,213,213,0],[128,213,155,0],[144,239,102,0],[160,249,0,68],[176,225,0,134],[192,196,0,176],[208,163,0,207],[224,118,0,232],[240,0,50,252]],
	11: [[0,255,0,0],[42,255,255,0],[84,0,255,0],[128,0,255,255],[170,0,0,255],[212,255,0,255],[255,255,0,0]],
	13: [[0,120,0,0],[22,179,22,0],[51,255,104,0],[85,167,22,18],[135,100,0,103],[198,16,0,130],[255,0,0,160]],
	3: ["c1","c1","c2","c2"]
};
FXS.setPalettes(P);
const palIds = Object.keys(P).map(Number).filter(i => i > 5 && FXS.hasPal(i));

// metadata defaults ("sx=24,pal=50" after the 4th ';') from fxlist.txt
const META = {};
try {
	for (const l of fs.readFileSync(path.join(DIR, "fxlist.txt"), "utf8").split(/\r?\n/)) {
		const m = l.split("|")[2];
		if (!m) continue;
		const [name, rest = ""] = m.split("@"), d = {};
		(rest.split(";")[4] || "").split(",").forEach(kv => { const [k, v] = kv.split("="); if (v !== undefined) d[k] = +v; });
		META[name] = d;
	}
} catch (e) { /* no fxlist.txt: plain defaults */ }

// argument checks: colours must be integers 0..0xFFFFFFFF, indices integers (C passes int/uint32, JS would silently coerce)
const proto = Object.getPrototypeOf(FXS.makeSeg({}).S);
let bad = null;
const okc = c => Number.isInteger(c) && c >= 0 && c <= 0xFFFFFFFF;
const flag = m => { if (!bad) bad = m; };
for (const [k, ci] of [["setPixelColor", 1], ["addPixelColor", 1], ["blendPixelColor", 1], ["fill", 0]]) {
	const o = proto[k];
	proto[k] = function(...a) {
		if (ci && !Number.isInteger(a[0])) flag(`${k}: non-integer index ${a[0]}`);
		if (k == "setPixelColor" && a.length > 2) { if (!a.slice(1, 4).every(Number.isFinite)) flag(`${k}: bad r,g,b ${a.slice(1, 4)}`); }
		else if (!okc(a[ci])) flag(`${k}: bad colour ${a[ci]}`);
		return o.apply(this, a);
	};
}

function sets(name) {
	const d = META[name] || {}, reg = FXS.get(name), pal = d.pal ?? 0;
	return [
		Object.assign({sx: 128, ix: 128, c1: 128, c2: 128, c3: 16, pal, col: [0xFFA000, 0, 0]}, d),
		{sx: 0, ix: 0, c1: 0, c2: 0, c3: 0, pal: palIds[0] || 0, col: [0xFF0000, 0x0000FF, 0x00FF00]},
		{sx: 255, ix: 255, c1: 255, c2: 255, c3: 31, o1: 1, o2: 1, o3: 1, pal: 1, col: [[255, 160, 0, 40], [0, 0, 255], [0, 255, 0]]}
	].map(s => Object.assign(s, {fx: name, dpal: reg.opts.pal || d.pal}));
}
const fnv = (h, px) => { for (let i = 0; i < px.length; i++) { h ^= px[i]; h = Math.imul(h, 16777619); } return h >>> 0; };
function run(o, len, frames) { // -> {err, animated, ms, hash, fallback}
	H.seed(12345);
	FXS.audio.set({bpm: 120, level: 1});
	const seg = FXS.makeSeg(Object.assign({}, o, {len, t0: 600000})), E = seg.E, first = new Uint32Array(len);
	let animated = false, hash = 2166136261, ms = 0, fallback = false;
	bad = null;
	for (let f = 0; f < frames; f++) {
		const t0 = process.hrtime.bigint();
		try { FXS.step(seg); } catch (e) { return {err: `exception at frame ${f}: ${e.message}`}; }
		ms += Number(process.hrtime.bigint() - t0) / 1e6;
		if (bad) return {err: `frame ${f}: ${bad}`};
		for (const k of ["aux0", "aux1"]) if (!Number.isInteger(E[k]) || E[k] < 0 || E[k] > 65535) return {err: `frame ${f}: ${k}=${E[k]} not uint16`};
		if (!Number.isInteger(E.step) || E.step < 0 || E.step > 0xFFFFFFFF) return {err: `frame ${f}: step=${E.step} not uint32`};
		const px = seg.S.px;
		if (px.length !== len) return {err: `frame ${f}: S.px replaced (length ${px.length})`};
		if (!f) first.set(px); else if (!animated) for (let i = 0; i < len; i++) if (px[i] !== first[i]) { animated = true; break; }
		hash = fnv(hash, px);
		fallback = fallback || seg.S.palFallback;
	}
	return {animated, ms: ms / frames, hash, fallback};
}

// load the fx files, remember which file registered which effect
const byFile = [];
for (const f of files) {
	const before = new Set(FXS.names());
	try { require(f); } catch (e) { console.log(`LOAD FAIL ${path.basename(f)}: ${e.message}`); process.exitCode = 1; continue; }
	byFile.push([f, FXS.names().filter(n => !before.has(n))]);
}

let fails = 0, total = 0;
if (golden) {
	for (const [, list] of byFile) for (const name of list) {
		const s = sets(name), a = run(s[0], 30, 200), b = run(s[2], 150, 200);
		console.log(`${name.padEnd(24)} ${a.err ? "ERR" : a.hash.toString(16).padStart(8, "0")} ${b.err ? "ERR" : b.hash.toString(16).padStart(8, "0")}`);
	}
	return;
}
for (const [f, list] of byFile) {
	console.log(`== ${path.basename(f)} (${list.length} effects)`);
	for (const name of list) {
		total++;
		const reg = FXS.get(name), st = reg.opts.static || STATIC.has(name);
		let err = null, animated = false, ms150 = 0, n150 = 0, fb = false;
		for (const o of sets(name)) for (const len of LENS) {
			const r = run(o, len, FRAMES);
			if (r.err) { err = err || `${r.err} [sx=${o.sx} len=${len}]`; continue; }
			animated = animated || r.animated;
			fb = fb || r.fallback;
			if (len == 150) { ms150 += r.ms; n150++; }
		}
		const ms = n150 ? ms150 / n150 : 0;
		if (!err && !animated && !st) err = "never changes in any slider set (add {static:true} if static on the device)";
		if (!err && ms > MAXMS) err = `too slow: ${ms.toFixed(2)} ms/frame at len 150`;
		if (err) fails++;
		console.log(`${err ? "FAIL" : "PASS"} ${name.padEnd(24)} ${ms.toFixed(3).padStart(6)} ms  ${String(gz(reg.fn.toString())).padStart(5)} B gz${fb ? "  (palette fallback)" : ""}${err ? "  " + err : ""}`);
	}
}

// size report
const src = f => fs.readFileSync(f, "utf8"), core = src(path.join(DIR, "core.js")), all = [core, ...byFile.map(([f]) => src(f))].join("\n");
console.log(`\n${total - fails}/${total} PASS`);
console.log(`gzip core.js ${gz(core)} B`);
for (const [f] of byFile) console.log(`gzip ${path.basename(f)} ${gz(src(f))} B`);
console.log(`gzip combined ${gz(all)} B`);
const tp = path.join(REPO, "node_modules", "terser");
if (fs.existsSync(tp)) require(tp).minify(all, {compress: true, mangle: true}).then(r => console.log(`terser+gzip combined ${gz(r.code)} B`), e => console.log(`terser failed: ${e.message}`));
if (fails) process.exitCode = 1;
// AI: end
